export function inspectHouse(model,id){const h=householdIndex(model,id),house=houseFor(model,h);return{...clone(house),objects:house.objects.map(object=>({...clone(object),placement:effectiveObjectPlacement(object),placementBasis:object.placement?'Persisted authoritative room-local placement':'Deterministic synthetic default; not added to the saved object',footprint:clone(FURNITURE_FOOTPRINTS[object.type]??null)})),placementRules:clone(HOUSE_PLACEMENT_RULES),persisted:!!storedHouse(model,h),limits:{maxChangedHouseholds:128,maxActiveResidents:32,maxCommands:256,maxObjects:64,maxPreparedServings:32,maxRetainedActions:64},mechanismFactors:house.rooms.map(room=>({roomId:room.id,...roomQuality(model,house,room,model.minute)})),visitors:visitorRows(model,house.householdId),guests:visitorRows(model,house.householdId).map(guest=>({...guest,...inspectHouseMember(model,guest.index,house),guest:true,label:guest.label,status:guest.status,canSendHome:guest.canSendHome})),minute:model.minute,clock:{minute:model.minute,tick:model.tick,source:'Committed population clock'},members:members(model,h).map(i=>inspectHouseMember(model,i,house)),actionCatalog:clone(HOUSE_ACTIONS),furnitureCatalog:Object.fromEntries(Object.entries(HOUSE_FURNITURE).map(([type,definition])=>[type,{...clone(definition),...clone(FURNITURE_FOOTPRINTS[type])}])),unavailable:clone(HOUSE_UNAVAILABLE),external:{annualHouseholdIncome:model.households.income[h],monthlyRent:model.households.rent[h],actualSavings:model.households.savings[h],housingStress:model.households.stress[h],weather:model.weather?clone(model.weather):null},ledger:'Savings and needs above belong to the same authoritative population entities; interior state has no separate cash/person model.'};}

/** Optional additive interior state: old 1.3 saves without houses remain exact. */
export function validateHouseState(model){const state=model.houses;if(state===undefined)return;check(state?.schemaVersion===HOUSE_VERSION&&state.homes&&state.active&&typeof state.homes==='object'&&typeof state.active==='object'&&!Array.isArray(state.homes)&&!Array.isArray(state.active),'Unsupported or invalid optional house state');check(Object.keys(state.homes).length<=128&&Object.keys(state.active).length<=32,'Interior state exceeds retention bounds');for(const [key,house]of Object.entries(state.homes)){const h=householdIndex(model,Number(key));if(house.wallLayout!==undefined){check(house.wallLayout.schemaVersion===HOUSE_WALL_VERSION,'Unknown wall layout version');normalizeHouseWalls(house.wallLayout.walls);}check(String(h)===key&&house.schemaVersion===HOUSE_VERSION&&house.householdId===`${model.prefix}-h${h}`,'Invalid interior household identity');check(Array.isArray(house.rooms)&&[4,5].includes(house.rooms.length)&&new Set(house.rooms.map(r=>r.id)).size===house.rooms.length&&house.rooms.every(r=>['bedroom','kitchen','living','study','garden'].includes(r.id)&&['noise','light','privacy','cleanliness'].every(k=>Number.isFinite(r[k])&&r[k]>=0&&r[k]<=1)),'Invalid interior room state');check(Number.isSafeInteger(house.nextAction)&&house.nextAction>=0&&house.totals&&Object.values(house.totals).every(v=>Number.isFinite(v)&&v>=0)&&Array.isArray(house.objects)&&house.objects.length<=64&&Array.isArray(house.actions)&&house.actions.length<=32&&Array.isArray(house.completedActions)&&house.completedActions.length<=64&&Array.isArray(house.transactions)&&house.transactions.length<=64&&Number.isInteger(house.preparedServings)&&house.preparedServings>=0&&house.preparedServings<=32,'Invalid interior inventory/history');for(const action of house.actions)check(Object.hasOwn(HOUSE_ACTIONS,action.type)&&Array.isArray(action.participants)&&action.participants.length>=1&&action.participants.length<=8&&action.participants.every(i=>Number.isInteger(i)&&(model.people.household[i]===h||action.type==='conversation'&&personAtHouse(model,i,house))&&Number.isFinite(action.progress[i])&&action.progress[i]>=0&&action.progress[i]<=action.durationMinutes+1e-6)&&Number.isFinite(action.start)&&action.until===action.start+action.durationMinutes,'Invalid interior action');for(const action of house.actions)if(action.seatIndices!==undefined){const target=actionObject(house,action);check(target?.type==='diningTable'&&Array.isArray(action.seatIndices)&&action.seatIndices.length===action.participants.length&&new Set(action.seatIndices).size===action.seatIndices.length&&action.seatIndices.every(seat=>Number.isInteger(seat)&&seat>=0&&seat<target.capacity),'Invalid retained dining seat reservation');}}for(const [key,active]of Object.entries(state.active)){const i=Number(key);check(Number.isInteger(i)&&i>=0&&i<model.people.age.length&&state.homes[active.household]?.actions.some(action=>action.id===active.actionId&&action.participants.includes(i)),'Invalid active interior resident');}}

export function releaseHouseVisitParticipant(model,i,minute){const entry=activeEntry(model,i);if(!entry)return;const {house,action}=entry;for(const j of action.participants)delete model.houses.active[j];house.actions=house.actions.filter(a=>a.id!==action.id);house.interruptedActions=[...(house.interruptedActions??[]),{actionId:action.id,type:action.type,minute,reason:'Visitor returning home',actualPersonMinutes:Object.values(action.progress).reduce((a,b)=>a+b,0),noCompletionGranted:true}].slice(-64);recordEvent(model,'HOUSEHOLD_ACTION_INTERRUPTED',{minute,householdId:house.householdId,actionId:action.id,reason:'Visitor returning home'});}
